import base64
from datetime import date
import json
import zlib

from django.db import migrations


# Snapshot generated 2026-08-06 from Salesforce Primary Company accounts.
# It contains 504 exact company-name/latest-visit pairs. Keeping the snapshot
# inside this one-time migration makes the production update deterministic and
# prevents the deploy from depending on Salesforce availability.
_SALESFORCE_LAST_VISITS = ""


def backfill_last_visit_dates(apps, schema_editor):
    Company = apps.get_model("core", "Company")
    records = json.loads(
        zlib.decompress(base64.b64decode(_SALESFORCE_LAST_VISITS)).decode()
    )

    for company_name, last_visit in records:
        Company.objects.filter(name__iexact=company_name).update(
            imported_last_visit_date=date.fromisoformat(last_visit)
        )


class Migration(migrations.Migration):
    dependencies = [
        ("core", "0028_company_imported_last_visit_date"),
    ]

    operations = [
        migrations.RunPython(
            backfill_last_visit_dates,
            reverse_code=migrations.RunPython.noop,
        ),
    ]
